package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen1Test {

    @Test
    public void testParseOctal_ValidBasic() {
        byte[] buffer = "0001234".getBytes();
        assertEquals(868L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "   0755".getBytes();
        assertEquals(493L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_WithTrailingSpacesAndNuls() {
        byte[] buffer = "0123   \0\0".getBytes();
        // "0123" octal is 83 decimal
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_LeadingZeroByte() {
        byte[] buffer = new byte[]{0, 0, 0};
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 3));
    }

    @Test
    public void testParseOctal_OffsetAndLength() {
        byte[] buffer = "junk0123junk".getBytes();
        // offset 4, length 4 -> "0123"
        assertEquals(83L, TarUtils.parseOctal(buffer, 4, 4));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = "0".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidCharacters() {
        byte[] buffer = "0128".getBytes(); // 8 is not octal
        TarUtils.parseOctal(buffer, 0, buffer.length);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidCharactersAlpha() {
        byte[] buffer = "012A".getBytes();
        TarUtils.parseOctal(buffer, 0, buffer.length);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_EmptyAfterTrimming() {
        byte[] buffer = "    \0\0".getBytes();
        // After skipping spaces and trimming NULs/spaces, start will equal end
        TarUtils.parseOctal(buffer, 0, buffer.length);
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Max octal for long is roughly 17777777777777777777 (too big for signed long)
        // Let's use a large but safe one
        byte[] buffer = "7777777777".getBytes(); 
        long expected = Long.parseLong("7777777777", 8);
        assertEquals(expected, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_LeadingSpacesAndTrailingNulsMixed() {
        // Testing the logic where trailing is a mix of NUL and space
        byte[] buffer = "  0777 \0 ".getBytes();
        assertEquals(511L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_StartIsImmediatelyZeroByte() {
        // If buffer[start] == 0, it returns 0L immediately
        byte[] buffer = new byte[]{0, 1, 2, 3};
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 4));
    }

    @Test
    public void testParseOctal_AllSpaces() {
        byte[] buffer = "      ".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, buffer.length);
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // Success
        }
    }
}
